// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@pythnetwork/entropy-sdk-solidity/IEntropy.sol";
import "@pythnetwork/entropy-sdk-solidity/IEntropyConsumer.sol";

contract CoinFlip is IEntropyConsumer {
    IEntropy private entropy;

    struct FlipRequest {
        address player;
        bool prediction; // true for heads, false for tails
        uint64 sequenceNumber;
        bool fulfilled;
        bool result; // true for heads, false for tails
    }

    mapping(uint64 => FlipRequest) public flipRequests;
    mapping(address => uint64[]) public playerFlips;

    event CoinFlipped(address indexed player, uint64 sequenceNumber, bool prediction);
    event FlipResult(address indexed player, uint64 sequenceNumber, bool result, bool won);

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
    }

    function flipCoin(bool _prediction, bytes32 _userRandomNumber) external payable {
        // Request entropy fee
        uint256 fee = entropy.getFee(entropy.getDefaultProvider());
        require(msg.value >= fee, "Insufficient fee");

        // Request random number
        uint64 sequenceNumber = entropy.requestWithCallback{value: fee}(
            entropy.getDefaultProvider(),
            _userRandomNumber
        );

        // Store flip request
        flipRequests[sequenceNumber] = FlipRequest({
            player: msg.sender,
            prediction: _prediction,
            sequenceNumber: sequenceNumber,
            fulfilled: false,
            result: false
        });

        playerFlips[msg.sender].push(sequenceNumber);

        emit CoinFlipped(msg.sender, sequenceNumber, _prediction);

        // Refund excess payment
        if (msg.value > fee) {
            payable(msg.sender).transfer(msg.value - fee);
        }
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address,
        bytes32 randomNumber
    ) internal override {
        FlipRequest storage request = flipRequests[sequenceNumber];
        require(!request.fulfilled, "Already fulfilled");

        // Convert random number to coin flip (true = heads, false = tails)
        bool result = uint256(randomNumber) % 2 == 0;

        request.result = result;
        request.fulfilled = true;

        bool won = (result == request.prediction);

        emit FlipResult(request.player, sequenceNumber, result, won);
    }

    function getFlipResult(uint64 sequenceNumber) external view returns (
        address player,
        bool prediction,
        bool result,
        bool fulfilled,
        bool won
    ) {
        FlipRequest memory request = flipRequests[sequenceNumber];
        return (
            request.player,
            request.prediction,
            request.result,
            request.fulfilled,
            request.fulfilled && (request.result == request.prediction)
        );
    }

    function getPlayerFlips(address player) external view returns (uint64[] memory) {
        return playerFlips[player];
    }

    function getEntropyFee() external view returns (uint256) {
        return entropy.getFee(entropy.getDefaultProvider());
    }

    // Allow contract to receive ETH for fees
    receive() external payable {}
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

// Interface for Pyth Entropy
interface IEntropy {
    function requestWithCallback(
        address provider,
        bytes32 userRandomNumber
    ) external payable returns (uint64 sequenceNumber);

    function getFee(address provider) external view returns (uint256 fee);
    function getDefaultProvider() external view returns (address);
}

interface IEntropyConsumer {
    function entropyCallback(
        uint64 sequenceNumber,
        address provider,
        bytes32 randomNumber
    ) external;
}

contract CoinFlip is IEntropyConsumer {
    IEntropy private entropy;
    address private entropyAddress;

    struct FlipRequest {
        address player;
        bool prediction; // true for heads, false for tails
        uint64 sequenceNumber;
        bool fulfilled;
        bool result; // true for heads, false for tails
    }

    mapping(uint64 => FlipRequest) public flipRequests;
    mapping(address => uint64[]) public playerFlips;

    event CoinFlipped(address indexed player, uint64 sequenceNumber, bool prediction);
    event FlipResult(address indexed player, uint64 sequenceNumber, bool result, bool won);

    modifier onlyEntropy() {
        require(msg.sender == entropyAddress, "Only entropy contract can call this");
        _;
    }

    constructor(address _entropy) {
        entropy = IEntropy(_entropy);
        entropyAddress = _entropy;
    }

    function flipCoin(bool _prediction, bytes32 _userRandomNumber) external payable {
        // Request entropy fee
        uint256 fee = entropy.getFee(entropy.getDefaultProvider());
        require(msg.value >= fee, "Insufficient fee for randomness");

        // Request random number
        uint64 sequenceNumber = entropy.requestWithCallback{value: fee}(
            entropy.getDefaultProvider(),
            _userRandomNumber
        );

        // Store flip request
        flipRequests[sequenceNumber] = FlipRequest({
            player: msg.sender,
            prediction: _prediction,
            sequenceNumber: sequenceNumber,
            fulfilled: false,
            result: false
        });

        playerFlips[msg.sender].push(sequenceNumber);

        emit CoinFlipped(msg.sender, sequenceNumber, _prediction);

        // Refund excess payment
        if (msg.value > fee) {
            payable(msg.sender).transfer(msg.value - fee);
        }
    }

    function entropyCallback(
        uint64 sequenceNumber,
        address,
        bytes32 randomNumber
    ) external override onlyEntropy {
        FlipRequest storage request = flipRequests[sequenceNumber];
        require(request.player != address(0), "Invalid sequence number");
        require(!request.fulfilled, "Already fulfilled");

        // Convert random number to coin flip (true = heads, false = tails)
        bool result = uint256(randomNumber) % 2 == 0;

        request.result = result;
        request.fulfilled = true;

        bool won = (result == request.prediction);

        emit FlipResult(request.player, sequenceNumber, result, won);
    }

    function getFlipResult(uint64 sequenceNumber) external view returns (
        address player,
        bool prediction,
        bool result,
        bool fulfilled,
        bool won
    ) {
        FlipRequest memory request = flipRequests[sequenceNumber];
        return (
            request.player,
            request.prediction,
            request.result,
            request.fulfilled,
            request.fulfilled && (request.result == request.prediction)
        );
    }

    function getPlayerFlips(address player) external view returns (uint64[] memory) {
        return playerFlips[player];
    }

    function getEntropyFee() external view returns (uint256) {
        return entropy.getFee(entropy.getDefaultProvider());
    }

    // Allow contract to receive ETH for fees
    receive() external payable {}
}

#root {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem;
  text-align: center;
}

.app {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

.app-header h1 {
  font-size: 3rem;
  margin-bottom: 0.5rem;
  text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
}

.app-header p {
  font-size: 1.2rem;
  margin-bottom: 2rem;
  opacity: 0.9;
}

.game-container {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2rem;
}

.stats {
  display: flex;
  gap: 2rem;
  background: rgba(255, 255, 255, 0.1);
  padding: 1rem 2rem;
  border-radius: 20px;
  backdrop-filter: blur(10px);
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
}

.stat-value {
  font-size: 2rem;
  font-weight: bold;
  color: #ffd700;
}

.stat-label {
  font-size: 0.9rem;
  opacity: 0.8;
}

.coin-container {
  perspective: 1000px;
  margin: 2rem 0;
}

.coin {
  width: 150px;
  height: 150px;
  position: relative;
  transform-style: preserve-3d;
  transition: transform 2s ease-in-out;
  margin: 0 auto;
}

.coin.flipping {
  animation: coinFlip 2s ease-in-out;
}

@keyframes coinFlip {
  0% { transform: rotateY(0deg) rotateX(0deg); }
  25% { transform: rotateY(450deg) rotateX(180deg); }
  50% { transform: rotateY(900deg) rotateX(360deg); }
  75% { transform: rotateY(1350deg) rotateX(540deg); }
  100% { transform: rotateY(1800deg) rotateX(720deg); }
}

.coin-side {
  position: absolute;
  width: 100%;
  height: 100%;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 4rem;
  font-weight: bold;
  border: 4px solid #ffd700;
  box-shadow: 0 8px 20px rgba(0,0,0,0.3);
  backface-visibility: hidden;
}

.coin-side.heads {
  background: linear-gradient(135deg, #ffd700, #ffed4e);
  color: #8b4513;
  transform: rotateY(0deg);
}

.coin-side.tails {
  background: linear-gradient(135deg, #c0c0c0, #e8e8e8);
  color: #4a4a4a;
  transform: rotateY(180deg);
}

.coin.heads {
  transform: rotateY(0deg);
}

.coin.tails {
  transform: rotateY(180deg);
}

.reaction {
  background: rgba(255, 255, 255, 0.1);
  padding: 1.5rem;
  border-radius: 20px;
  backdrop-filter: blur(10px);
  max-width: 400px;
  animation: fadeInUp 0.5s ease-out;
}

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.reaction.correct {
  border: 2px solid #4ade80;
  box-shadow: 0 0 20px rgba(74, 222, 128, 0.3);
}

.reaction.incorrect {
  border: 2px solid #f87171;
  box-shadow: 0 0 20px rgba(248, 113, 113, 0.3);
}

.reaction-message {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  font-weight: bold;
}

.reaction.correct .reaction-message {
  color: #4ade80;
}

.reaction.incorrect .reaction-message {
  color: #f87171;
}

.result-details {
  font-size: 1rem;
  opacity: 0.9;
}

.controls {
  display: flex;
  gap: 2rem;
  margin-top: 2rem;
}

.flip-btn {
  padding: 1rem 2rem;
  font-size: 1.2rem;
  border: none;
  border-radius: 50px;
  cursor: pointer;
  transition: all 0.3s ease;
  background: linear-gradient(135deg, #667eea, #764ba2);
  color: white;
  box-shadow: 0 4px 15px rgba(0,0,0,0.2);
  min-width: 120px;
}

.flip-btn:hover:not(:disabled) {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(0,0,0,0.3);
}

.flip-btn:disabled {
  opacity: 0.6;
  cursor: not-allowed;
  transform: none;
}

.heads-btn {
  background: linear-gradient(135deg, #ffd700, #ffed4e);
  color: #8b4513;
}

.tails-btn {
  background: linear-gradient(135deg, #c0c0c0, #e8e8e8);
  color: #4a4a4a;
}

.reset-btn {
  padding: 0.75rem 1.5rem;
  font-size: 1rem;
  border: 2px solid rgba(255, 255, 255, 0.3);
  border-radius: 25px;
  background: rgba(255, 255, 255, 0.1);
  color: white;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 1rem;
}

.reset-btn:hover {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.5);
}

.flipping-message {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: rgba(0, 0, 0, 0.8);
  padding: 2rem;
  border-radius: 20px;
  backdrop-filter: blur(10px);
  text-align: center;
}

.spinner {
  font-size: 3rem;
  animation: spin 1s linear infinite;
  margin-bottom: 1rem;
}

@keyframes spin {
  from { transform: rotate(0deg); }
  to { transform: rotate(360deg); }
}

footer {
  margin-top: 2rem;
  padding: 1rem;
  opacity: 0.7;
}

@media (max-width: 768px) {
  .app-header h1 {
    font-size: 2rem;
  }

  .stats {
    gap: 1rem;
    padding: 0.75rem 1rem;
  }

  .controls {
    flex-direction: column;
    gap: 1rem;
    align-items: center;
  }

  .flip-btn {
    min-width: 200px;
  }
}

:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
  color-scheme: light dark;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  min-height: 100vh;
}

